import { readFileSync } from "node:fs";
import { join, relative } from "node:path";
import { formatCount } from "../../formatting.js";
import { findProjectRoot } from "../../paths.js";
import { isApiServiceType } from "../../resource-kind.js";
import { discoverResourcesFromRoot } from "../../services.js";
import { COMMENT_LINE, listSourceFiles, projectName } from "./shared.js";
/** Backends are the only resources that listen on their `port`. */
function backendPorts(resources) {
    const ports = new Map();
    for (const resource of resources) {
        const port = resource.config?.port;
        if (isApiServiceType(resource.config?.appType) && typeof port === "number") {
            ports.set(resource.name, port);
        }
    }
    return ports;
}
function readParams(configPath) {
    try {
        const params = JSON.parse(readFileSync(configPath, "utf-8")).params;
        return params && typeof params === "object" ? params : {};
    }
    catch {
        return {};
    }
}
const CONTAINER_URL = /https?:\/\/([a-z][a-z0-9-]*):(\d+)/g;
export function checkServiceUrlPorts(projectRoot = findProjectRoot() ?? process.cwd()) {
    const resources = discoverResourcesFromRoot(projectRoot);
    const ports = backendPorts(resources);
    const byPort = new Map([...ports].map(([name, port]) => [port, name]));
    const problems = [];
    for (const resource of resources) {
        for (const [key, value] of Object.entries(readParams(resource.configPath))) {
            for (const [, host, portText] of String(value).matchAll(CONTAINER_URL)) {
                const port = Number(portText);
                const expected = ports.get(host);
                if (expected !== undefined && expected !== port) {
                    problems.push(`${resource.name} param ${key}: ${host}:${port}, but ${host} listens on ${expected}`);
                }
                else if ((host === "localhost" || host === "127.0.0.1") &&
                    byPort.has(port) &&
                    byPort.get(port) !== resource.name) {
                    problems.push(`${resource.name} param ${key}: localhost:${port} is ${resource.name} itself inside its container; ${byPort.get(port)} is reached as ${byPort.get(port)}:${port}`);
                }
            }
        }
    }
    if (problems.length === 0) {
        return {
            name: "Service URL ports",
            didPass: true,
            message: "Service URLs in params point at the ports the services listen on",
        };
    }
    return {
        name: "Service URL ports",
        didPass: false,
        message: `${formatCount(problems.length, "service URL")} in params that cannot connect:\n    ${problems.join("\n    ")}`,
        fix: 'Flisk runs each backend on the "port" in its service.json, and containers reach each other by resource name (http://<resource>:<port>). Use that port in the URL',
    };
}
const LOCALHOST_PORT = /(?:localhost|127\.0\.0\.1):(\d{2,5})\b/g;
export function checkFrontendBackendUrls(projectRoot = findProjectRoot() ?? process.cwd()) {
    const resources = discoverResourcesFromRoot(projectRoot);
    const byPort = new Map([...backendPorts(resources)].map(([name, port]) => [port, name]));
    const problems = [];
    for (const resource of resources.filter((r) => r.config?.appType === "frontend")) {
        for (const file of listSourceFiles(join(resource.path, "src"))) {
            readFileSync(file, "utf-8")
                .split("\n")
                .forEach((line, index) => {
                if (COMMENT_LINE.test(line))
                    return;
                for (const [, portText] of line.matchAll(LOCALHOST_PORT)) {
                    const backend = byPort.get(Number(portText));
                    if (backend) {
                        problems.push(`${relative(projectRoot, file)}:${index + 1} calls localhost:${portText} (${backend})`);
                    }
                }
            });
        }
    }
    if (problems.length === 0) {
        return {
            name: "Frontend backend URLs",
            didPass: true,
            message: "No frontend calls a backend through a localhost port",
        };
    }
    const project = projectName(projectRoot) ?? "<project>";
    return {
        name: "Frontend backend URLs",
        didPass: false,
        message: `${formatCount(problems.length, "frontend call")} to a backend port that Flisk does not publish on localhost:\n    ${problems.join("\n    ")}`,
        fix: `Backends are only reachable through Traefik: http://api.${project}.localhost/api/<name without -api>/... (for example catalog-api is /api/catalog). Use that URL, or the generated .autogenerated/env.ts`,
    };
}
